
import type { ImageInput } from './ImageInput.js';
import type { MoneyValueInput } from './MoneyValueInput.js';

/** Subscription terms shown before an active plan-backed payment link creates a checkout session. */ export type PaymentLinkSubscriptionPreviewInput = { "billing_interval": "daily" | "weekly" | "monthly" | "yearly"; /** Number of billing intervals between recurring charges. Format: int32. */ "billing_interval_count": number; /** Minimum contract term in months, when configured. Format: int32. */ "contract_term_months"?: number; /** True when the plan has a line that ships or is delivered, so each renewal adds a shipping or delivery charge chosen at checkout. The amount is not known until the buyer enters an address and chooses a method. */ "delivery_required"?: never; /** Early termination fee, when configured. */ "early_termination_fee_money"?: MoneyValueInput; /** Plan image shown to the buyer, when configured. */ "plan_image"?: ImageInput; /** Plan name shown to the buyer. */ "plan_name": string; /** Recurring total for one billing interval, including line quantities and resolved modifiers. */ "recurring_total_money": MoneyValueInput; /** Setup fee added to the first amount due, when configured. */ "setup_fee_money"?: MoneyValueInput; /** Number of trial days before the first recurring charge, when configured. Format: int32. */ "trial_period_days"?: number; };
